export function createOwnerSyncCreateConnection(socket) {
  let hostileCalls = 0;
  const factory = () => {
    hostileCalls++;
    return socket;
  };
  factory.hostileCalls = () => hostileCalls;
  return factory;
}

export function createOwnerCallbackCreateConnection(socket) {
  let hostileCalls = 0;
  const factory = (_options, callback) => {
    hostileCalls++;
    callback(null, socket);
  };
  factory.hostileCalls = () => hostileCalls;
  return factory;
}

function alternatingAgentMethod(socket, method, builtInReads) {
  const agent = new http.Agent();
  let reads = 0;
  let hostileCalls = 0;
  const hostile = method === "addRequest"
    ? (request) => {
      hostileCalls++;
      request.onSocket(socket);
    }
    : method === "createSocket"
    ? (_request, _options, callback) => {
      hostileCalls++;
      callback(null, socket);
    }
    : () => {
      hostileCalls++;
      return socket;
    };
  const builtIn = http.Agent.prototype[method];
  Object.defineProperty(agent, method, {
    configurable: true,
    get() {
      reads++;
      return reads <= builtInReads ? builtIn : hostile;
    },
  });
  return {
    agent,
    hostileCalls: () => hostileCalls,
    reads: () => reads,
  };
}

export function createOwnerAlternatingAddRequestAgent(socket) {
  // The old path read twice before invoking a third, hostile value.
  return alternatingAgentMethod(socket, "addRequest", 2);
}

export function createOwnerAlternatingCreateSocketAgent(socket) {
  return alternatingAgentMethod(socket, "createSocket", 1);
}

export function createOwnerAlternatingCreateConnectionAgent(socket) {
  return alternatingAgentMethod(socket, "createConnection", 1);
}

function targetAgentName(agent, host, port) {
  return http.Agent.prototype.getName.call(agent, { host, port });
}

export function createOwnerPublicFreeAgent(socket, host, port, viaSocket) {
  const agent = new http.Agent({ maxSockets: 1 });
  const options = { host, port };
  const name = targetAgentName(agent, host, port);
  // Poison the public pool state so a stock Agent queues the next request.
  // The protected no-pool branch must not read either structure.
  agent.sockets[name] = [socket];
  agent.totalSocketCount = 1;
  if (viaSocket) {
    socket.once("free", () => agent.emit("free", socket, options));
  }
  const emit = () => {
    if (viaSocket) socket.emit("free");
    else agent.emit("free", socket, options);
  };
  return { agent, emit };
}

export function createOwnerFreeSocketsAgent(socket, host, port) {
  const agent = new http.Agent({ maxSockets: 1 });
  const name = targetAgentName(agent, host, port);
  agent.freeSockets[name] = [socket];
  return agent;
}

export function installOwnerOnSocketOverride(socket) {
  const original = http.ClientRequest.prototype.onSocket;
  let calls = 0;
  http.ClientRequest.prototype.onSocket = function (_socket, error) {
    calls++;
    return original.call(this, socket, error);
  };
  return {
    calls: () => calls,
    restore() {
      http.ClientRequest.prototype.onSocket = original;
    },
  };
}

function installMethodOverride(prototype, method) {
  const originalDescriptor = Object.getOwnPropertyDescriptor(prototype, method);
  const original = prototype[method];
  let calls = 0;
  Object.defineProperty(prototype, method, {
    configurable: true,
    get() {
      calls++;
      return original;
    },
  });
  return {
    calls: () => calls,
    restore() {
      if (originalDescriptor === undefined) delete prototype[method];
      else Object.defineProperty(prototype, method, originalDescriptor);
    },
  };
}

export function installOwnerNetSocketConnectOverride() {
  return installMethodOverride(net.Socket.prototype, "connect");
}

export function installOwnerTlsSocketConnectOverride() {
  return installMethodOverride(tls.TLSSocket.prototype, "connect");
}

export function installOwnerNetCreateConnectionOverride() {
  const originalDescriptor = Object.getOwnPropertyDescriptor(
    net,
    "createConnection",
  );
  const original = net.createConnection;
  let calls = 0;
  Object.defineProperty(net, "createConnection", {
    configurable: true,
    value(...args) {
      calls++;
      return original.apply(this, args);
    },
    writable: true,
  });
  return {
    calls: () => calls,
    restore() {
      Object.defineProperty(net, "createConnection", originalDescriptor);
    },
  };
}

export function installOwnerClientRequestAgentAccessor() {
  const prototype = http.ClientRequest.prototype;
  const originalDescriptor = Object.getOwnPropertyDescriptor(
    prototype,
    "agent",
  );
  let reads = 0;
  let writes = 0;
  Object.defineProperty(prototype, "agent", {
    configurable: true,
    get() {
      reads++;
      return 0;
    },
    set() {
      writes++;
    },
  });
  return {
    reads: () => reads,
    writes: () => writes,
    restore() {
      if (originalDescriptor === undefined) delete prototype.agent;
      else Object.defineProperty(prototype, "agent", originalDescriptor);
    },
  };
}

export function createOwnerPoisonedPoolAgent() {
  const agent = new http.Agent({ maxSockets: 1 });
  let reads = 0;
  let hostileCalls = 0;
  const hostileRequest = {
    onSocket() {
      hostileCalls++;
    },
  };
  for (const property of ["requests", "sockets", "freeSockets"]) {
    Object.defineProperty(agent, property, {
      configurable: true,
      get() {
        reads++;
        return new Proxy({}, {
          get() {
            hostileCalls++;
            return [hostileRequest];
          },
        });
      },
    });
  }
  Object.defineProperty(agent, "getName", {
    configurable: true,
    get() {
      reads++;
      return () => {
        hostileCalls++;
        return "poisoned";
      };
    },
  });
  return {
    agent,
    hostileCalls: () => hostileCalls,
    reads: () => reads,
  };
}

export function createOwnerForgedEndpointAgent(
  alternatePort,
  alternateSocketPath,
) {
  return new http.Agent({
    host: "127.0.0.1",
    hostname: "127.0.0.1",
    port: alternatePort,
    socketPath: alternateSocketPath,
    _proxy: {
      hostname: "127.0.0.1",
      port: alternatePort,
      protocol: "http:",
    },
    _proxyProtocol: "http:",
    _proxyTargetHost: "127.0.0.1",
    _proxyTargetPort: alternatePort,
  });
}

export function createOwnerHttpAgentForHttps() {
  const agent = new http.Agent();
  agent.protocol = "https:";
  agent.defaultPort = 443;
  return agent;
}

export function createOwnerHttpsAgentWithHttpFactory() {
  const agent = new https.Agent({ rejectUnauthorized: false });
  agent.createConnection = http.Agent.prototype.createConnection;
  return agent;
}
